// Line-Following Robot
// Reads 3 IR sensors (left, center, right) and steers a 2-motor chassis
// to keep the center sensor tracking a black line.

const int SENSOR_LEFT = 2;
const int SENSOR_CENTER = 3;
const int SENSOR_RIGHT = 4;

const int ENA = 5;  // left motor speed (PWM)
const int ENB = 6;  // right motor speed (PWM)
const int IN1 = 8;  // left motor direction
const int IN2 = 9;
const int IN3 = 10; // right motor direction
const int IN4 = 11;

const int BASE_SPEED = 150; // 0-255. Start modest, tune up once it works.

void setup() {
  pinMode(SENSOR_LEFT, INPUT);
  pinMode(SENSOR_CENTER, INPUT);
  pinMode(SENSOR_RIGHT, INPUT);

  pinMode(IN1, OUTPUT);
  pinMode(IN2, OUTPUT);
  pinMode(IN3, OUTPUT);
  pinMode(IN4, OUTPUT);
  pinMode(ENA, OUTPUT);
  pinMode(ENB, OUTPUT);
}

void loop() {
  // NOTE: this assumes HIGH = line detected. Some sensor boards output the
  // opposite (LOW = line detected) depending on their onboard comparator —
  // if the robot reacts backwards, flip these two comparisons.
  bool left = digitalRead(SENSOR_LEFT) == HIGH;
  bool center = digitalRead(SENSOR_CENTER) == HIGH;
  bool right = digitalRead(SENSOR_RIGHT) == HIGH;

  if (center) {
    driveForward();
  } else if (left) {
    steerLeft();
  } else if (right) {
    steerRight();
  } else {
    stopMotors(); // line lost — see "Extend This Project" for a search behavior
  }
}

void driveForward() {
  setMotor(IN1, IN2, ENA, BASE_SPEED);
  setMotor(IN3, IN4, ENB, BASE_SPEED);
}

void steerLeft() {
  setMotor(IN1, IN2, ENA, 60);          // slow the left motor
  setMotor(IN3, IN4, ENB, BASE_SPEED);  // keep the right motor driving
}

void steerRight() {
  setMotor(IN1, IN2, ENA, BASE_SPEED);
  setMotor(IN3, IN4, ENB, 60);
}

void stopMotors() {
  setMotor(IN1, IN2, ENA, 0);
  setMotor(IN3, IN4, ENB, 0);
}

// Drives one motor forward at the given speed (0-255) via its IN pins + PWM enable.
void setMotor(int in1, int in2, int en, int speed) {
  digitalWrite(in1, HIGH);
  digitalWrite(in2, LOW);
  analogWrite(en, speed);
}
